    fetch(`/api/skeleton/${encodeURIComponent(ARTICLE)}`)
      .then((response) =>
        response.ok ? response.json() : Promise.reject(new Error(`HTTP ${response.status}`)),
      )
      .then(setArticle, (failure: Error) => setError(failure.message))
