  await send("Page.navigate", { url });
  const deadline = Date.now() + 30000;
  while (!(await evaluate(`!!document.body?.innerText.includes(${JSON.stringify(waitText)})`))) {
    if (Date.now() > deadline) throw new Error(`no "${waitText}" on the page after 30 s`);
