"""For each sampled reprint pair: the share of the shorter text's 5-word runs found in the longer."""
import json, re, sys, zstandard
from collections import defaultdict
W = re.compile(r"[a-z]{3,}")
def runs(text):
    w = W.findall(text.replace("-\n", "").lower())
    return {" ".join(w[i:i + 5]) for i in range(len(w) - 4)}
checks = json.load(open("eval/results/eval_a/reprint-check.json"))
want = defaultdict(set)
for c in checks:
    for m in c["members"]:
        want[re.search(r"_(\d{4})-\d\d-\d\d_", m)[1]].add(m)
text = {}
for year, ids in want.items():
    for line in zstandard.open(f"data/candidates/{year}.jsonl.zst", "rt"):
        r = json.loads(line)
        if r["article_id"] in ids:
            text[r["article_id"]] = r["text"] or ""
for n, c in enumerate(checks, 1):
    a, b = (runs(text[m]) for m in c["members"])
    small, big = sorted((a, b), key=len)
    shared = small & big
    print(f"{n:2} containment {len(shared) / max(1, len(small)):.2f} ({len(shared)} of {len(small)} runs; other has {len(big)})", "| e.g.", next(iter(sorted(shared)), "")[:60])
